import os,sys,json,base64,shutil,subprocess
from pathlib import Path
inp,work=Path('/kaggle/input'),Path('/kaggle/working')
subject='B'
root=next(inp.rglob('scripts/export_authenticity_features.py')).parents[1]
code=work/'code'
shutil.copytree(root,code,dirs_exist_ok=True)
patches=json.loads(base64.b64decode(''))
for name,text in patches.items():
    (code/name).write_text(text)
os.environ['PYTHONPATH']=os.pathsep.join([str(code),str(code/'tests')])
subprocess.run([sys.executable,'-m','pip','install','-e',str(code),'pytest'],check=True)
subprocess.run([sys.executable,'-m','pytest','-q','tests/test_spatiotemporal_features.py','tests/test_export_authenticity_features.py'],cwd=code,check=True)
clean=next(inp.rglob(subject+'_clean.npz'))
merged=work/'merged'
(merged/'attacks_eval').mkdir(parents=True,exist_ok=True)
(merged/'attacks_eval'/subject).symlink_to(clean.parent,target_is_directory=True)
out=work/'out'
out.mkdir(exist_ok=True)
(out/'overlay_provenance.json').write_text(json.dumps(dict(overlay_commit='09824a5',seed=20260929,subject=subject)))
for representation in ('summary','channel_time'):
    subprocess.run([sys.executable,str(code/'scripts/export_authenticity_features.py'),'--subject',subject,'--results-root',str(merged),'--out-dir',str(out/representation/subject),'--representation',representation,'--seed','20260929'],check=True)
